from __future__ import annotations

def cyclic_shift_probabilities(size: int, horizon: int) -> list[list[float]]:
    if size < 2 or horizon < 1:
        raise ValueError("size >= 2 and horizon >= 1 are required")
    return [[1.0 if x == n % size else 0.0 for x in range(size)] for n in range(horizon)]

def total_variation(p: list[float], q: list[float]) -> float:
    return 0.5 * sum(abs(a - b) for a, b in zip(p, q))

if __name__ == "__main__":
    n = 7
    uniform = [1.0 / n] * n
    for t, probability in enumerate(cyclic_shift_probabilities(n, n + 1)):
        print(t, probability, total_variation(probability, uniform))

from __future__ import annotations

def cesaro_cycle(size: int, horizon: int) -> list[float]:
    if size < 2 or horizon < 1:
        raise ValueError("size >= 2 and horizon >= 1 are required")
    counts = [0] * size
    for time in range(horizon):
        counts[time % size] += 1
    return [count / horizon for count in counts]

def total_variation(p: list[float], q: list[float]) -> float:
    return 0.5 * sum(abs(a - b) for a, b in zip(p, q))

if __name__ == "__main__":
    n = 9
    uniform = [1.0 / n] * n
    for horizon in (1, n, n + 4, 10 * n):
        average = cesaro_cycle(n, horizon)
        print(horizon, average, total_variation(average, uniform))

