import cmath
import math

def cyclic_shift_eigenvalues(size: int) -> list[complex]:
    if size < 2:
        raise ValueError("size must be at least two")
    return [cmath.exp(2j * math.pi * j / size) for j in range(size)]

if __name__ == "__main__":
    for eigenvalue in cyclic_shift_eigenvalues(8):
        print(f"{eigenvalue.real:+.6f}{eigenvalue.imag:+.6f}i  modulus={abs(eigenvalue):.12f}")

