from __future__ import annotations
from typing import Sequence

def matmul(a: Sequence[Sequence[complex]], b: Sequence[Sequence[complex]]) -> list[list[complex]]:
    n = len(a)
    return [[sum(a[i][k] * b[k][j] for k in range(n)) for j in range(n)] for i in range(n)]

def identity(n: int) -> list[list[complex]]:
    return [[1.0 + 0j if i == j else 0j for j in range(n)] for i in range(n)]

def matrix_power(a: Sequence[Sequence[complex]], exponent: int) -> list[list[complex]]:
    result = identity(len(a)); base = [list(row) for row in a]
    while exponent:
        if exponent & 1:
            result = matmul(result, base)
        base = matmul(base, base); exponent //= 2
    return result

def maximum_entry_error(a: Sequence[Sequence[complex]], b: Sequence[Sequence[complex]]) -> float:
    return max(abs(a[i][j] - b[i][j]) for i in range(len(a)) for j in range(len(a)))

def has_period(a: Sequence[Sequence[complex]], period: int, tolerance: float = 1e-10) -> bool:
    return period > 0 and maximum_entry_error(matrix_power(a, period), identity(len(a))) <= tolerance

from __future__ import annotations
from typing import Iterable, Sequence

def running_cesaro(distributions: Iterable[Sequence[float]]) -> list[list[float]]:
    total: list[float] = []
    averages: list[list[float]] = []
    for count, distribution in enumerate(distributions, start=1):
        if not total:
            total = [0.0] * len(distribution)
        if len(distribution) != len(total):
            raise ValueError("dimension changed")
        for x, value in enumerate(distribution):
            total[x] += value
        averages.append([value / count for value in total])
    return averages

from __future__ import annotations
import cmath
import math
from typing import Sequence

def wrapped_distance(a: float, b: float) -> float:
    difference = (a - b + math.pi) % (2.0 * math.pi) - math.pi
    return abs(difference)

def spectral_audit(eigenvalues: Sequence[complex]) -> tuple[float, float]:
    if len(eigenvalues) < 2:
        raise ValueError("at least two eigenvalues are required")
    modulus_error = max(abs(abs(value) - 1.0) for value in eigenvalues)
    phases = [cmath.phase(value) for value in eigenvalues]
    positive_gaps = [wrapped_distance(phases[i], phases[j]) for i in range(len(phases)) for j in range(i)]
    return modulus_error, min(positive_gaps)

